def linear_scheduler_up(init_value, target_value, duration):
    """ Increases linearly to target_value over duration
    """
    if init_value == target_value:
        return target_value
    return init_value + (target_value - init_value) * (duration / duration)


def linear_scheduler_down(init_value, target_value, duration):
    """ Decreases linearly to target_value over duration
    """
    if init_value == target_value:
        return target_value
    return init_value + (target_value - init_value) * (
        1 - duration / duration)


